document.querySelector("#batch39 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-15455356.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف الله\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>الله</h3><p>يقابل المقتطف المنشور بين تغير الظواهر الطبيعية والإنسانية، وبين تنزيه الله عن صفاتها في تصور مصطفى محمود. تتراكم صور الذبول والمرض والزوال لتقري…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/paranormal-special30.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف عدد خاص 30 : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا)\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>عدد خاص 30 : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا)</h3><p>تقدّم نبذة العدد مناسبة تتلاقى عندها مسارات رفعت إسماعيل وعلاء وعبير، أبطال عوالم مختلفة لأحمد خالد توفيق. يجمع الإطار الخاص فكرة المغامرة الثلاث…</p><small>أحمد خالد توفيق</small></a><a class=\"card\" href=\"summaries/paranormal-special7.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف أغاني المهد : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 7\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>أغاني المهد : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 7</h3><p>تنطلق نبذة أغاني المهد من عالم أغنيات الطفولة وما قد يختلط به من خوف ولعب. تنشأ المفارقة بين وظيفة الأغنية المطمئنة وما يوقظه الخيال فيها من احتم…</p><small>أحمد خالد توفيق</small></a>");
